"""One-off, scoped source transformation for the WorkBuddy-inspired UI review."""
from pathlib import Path

ROOT=Path(__file__).resolve().parent
p=ROOT/'app.js'
s=p.read_text(encoding='utf-8')
assert 'function sceneHome()' not in s, 'Layout transformation already applied'
s=s.replace("  S.page='home';S.role='全部';S.search='';S.selected=[];", "  S.page='home';S.scene='office';S.taskPrompt='';S.workspaceChoice='';S.accessMode='read-only';S.role='全部';S.search='';S.selected=[];",1)
start=s.index('  function shell(){')
end=s.index('  function pageContent()',start)
shell=r'''  const sceneInfo={
    office:{name:'办公',icon:'briefcase',subtitle:'把琐碎交给助手，把时间留给真正重要的事。',chips:[['知识整理','知识整理'],['面试题库','建题'],['AI 面试官','面试'],['复习计划','复习计划'],['创作文档','创作文档'],['课程复盘','课程复盘']],suggestions:[['book','从零建立一组 Agent 应用开发面试题','建题','结合工具调用、RAG 和项目实践，整理回答要点与追问。'],['mic','来一场 20 分钟的 Java 后端模拟面试','面试','从你的 5 年开发经验出发，练习原理、取舍与项目表达。'],['file','把这周的学习记录整理成一份复盘','知识整理','梳理重点、疑问和接下来值得练习的内容。'],['review','根据上次面试，安排一次针对性补练','复习计划','从真实回答里的卡点出发，不再反复刷已经会的题。']]},
    develop:{name:'开发',icon:'code',subtitle:'理解项目的来龙去脉，让每次实现都更有思路。',chips:[['项目理解','项目理解'],['代码讲解','代码讲解'],['接口设计','接口设计'],['问题排查','问题排查'],['技术方案','技术方案'],['项目面试','项目面试']],suggestions:[['folder','帮我理清 tiangong_agent 的请求调用链','项目理解','从接口到 Supervisor，再到专项工具与结果返回。'],['code','解释这段代码为什么要这样组织','代码讲解','拆开模块职责、数据流和实现顺序。'],['terminal','为一个可取消的 AI 任务设计接口','接口设计','先明确状态、输入输出和失败恢复边界。'],['mic','围绕我的项目，出一组深入追问题','项目面试','练习说清自己的实现、验证方法和工程取舍。']]},
    design:{name:'设计',icon:'spark',subtitle:'让一个模糊的想法，逐步变成可以看见的方案。',chips:[['界面草图','界面草图'],['交互流程','交互流程'],['演示文稿','演示文稿'],['信息架构','信息架构'],['方案排版','方案排版']],suggestions:[['layers','为学习与面试工作台梳理信息架构','信息架构','安排任务、资料、题库与成果之间的关系。'],['spark','设计一个清晰的 AI 面试对话界面','界面草图','让问题、回答、追问和复盘各有自己的位置。'],['file','把我的 Agent 项目整理成面试介绍稿','演示文稿','用背景、职责、难点和结果讲清一个真实项目。'],['review','设计一份方便回顾的学习报告版式','方案排版','让重点、来源和后续练习一眼就能找到。']]}
  };
  function shell(){
    const names={home:'新建任务',bank:'面试题库',build:'面试题整理',interview:'AI 面试官',report:'面试报告',review:'复习清单',agents:'专家 · 技能 · 连接器',workspace:'资料库',settings:'设置',tasks:'任务记录',assistant:'助理',automations:'定时任务',more:'更多应用',task:'任务预览'};
    const mainNav=[['home','plus','新建任务'],['assistant','bot','助理'],['agents','layers','专家 · 技能 · 连接器'],['automations','clock','定时任务'],['workspace','book','资料库'],['more','home','更多']];
    const module=sceneInfo[S.scene]||sceneInfo.office;
    const currentNav=['bank','build','interview','report','review','task'].includes(S.page)?'home':S.page;
    return `<div class="app-window wb-layout"><div class="titlebar"><div class="desktop-menu"><span class="titlebar-brand">${I('layers')} 知序</span><span class="desktop-menu-item">文件</span><span class="desktop-menu-item">窗口</span><span class="desktop-menu-item">帮助</span></div><span class="small">AI WORKBENCH · 前端评审原型</span><div class="window-controls" aria-hidden="true"><span>—</span><span>□</span><span>×</span></div></div><div class="layout"><aside class="sidebar"><div class="wb-brand"><div><div class="brand-name">知序<span class="brand-period">.</span></div><div class="brand-sub">YOUR AI WORKBENCH</div></div><button class="discovery-button" data-action="nav" data-page="more">${I('spark')}<span>发现应用</span>${I('down')}</button></div><nav class="nav wb-nav" aria-label="全局导航">${mainNav.map(([page,icon,label])=>`<button class="nav-item ${currentNav===page?'active':''}" data-action="nav" data-page="${page}" aria-label="${label}">${I(icon)}<span>${label}</span>${page==='assistant'?'<span class="beta-label">BETA</span>':''}</button>`).join('')}</nav><div class="sidebar-scroll"><div class="sidebar-section-head"><span>任务 <span class="dim">(${S.demoTasks?.length||3})</span></span><button class="icon-btn" data-action="nav" data-page="tasks" aria-label="查看全部任务">${I('history')}</button></div><button class="wb-task-link" data-action="resume"><span>Agent 应用开发 · 专项训练</span><i class="task-live-dot"></i></button><button class="wb-task-link" data-action="nav" data-page="bank"><span>工具调用与记忆 · 整理题库</span><small>今天</small></button><button class="wb-task-link" data-action="nav" data-page="review"><span>本周面试薄弱点复习</span><small>昨天</small></button>${(S.demoTasks||[]).slice(-2).reverse().map(t=>`<button class="wb-task-link" data-action="open-demo-task" data-id="${t.id}"><span>${E(t.title)}</span><small>刚刚</small></button>`).join('')}<button class="sidebar-more-link" data-action="nav" data-page="tasks">查看全部任务 ${I('chevron')}</button><div class="sidebar-section-head space-head"><span>空间 <span class="dim">(2)</span></span><button class="icon-btn" data-action="workspace-picker" aria-label="管理工作空间">${I('plus')}</button></div><button class="space-item" data-action="space-open" data-value="tiangong_agent">${I('folder')}<span>tiangong_agent</span></button><div class="space-description">Agent 学习与项目实践</div><button class="space-item" data-action="space-open" data-value="Java 项目与面试">${I('folder')}<span>Java 项目与面试</span></button><div class="space-description">工作经验与工程知识沉淀</div></div><div class="sidebar-bottom"><button class="nav-item ${S.page==='settings'?'active':''}" data-action="nav" data-page="settings" aria-label="设置">${I('settings')}<span>设置与工具</span></button><div class="user"><span class="avatar">我</span><div><strong>个人账户</strong><small>本地资料 · 云端能力</small></div><button class="icon-btn" data-action="help" aria-label="原型说明">${I('dots')}</button></div></div></aside><div class="main-shell ${S.page==='home'?'is-launcher':''}"><header class="topbar"><div class="breadcrumb">${S.page==='home'?'<span class="quiet-breadcrumb">一个入口，开始不同的工作</span>':`<button class="breadcrumb-back" data-action="nav" data-page="home">${module.name}</button>${I('chevron')}<strong>${names[S.page]||'任务'}</strong>`}</div><div class="top-actions"><span class="prototype-tag">交互原型 · 演示数据</span><button class="icon-btn" data-action="help" aria-label="查看原型说明">${I('info')}</button></div></header><main class="content" id="main-content"><div class="page ${S.page==='home'?'launcher-page':''}" id="page-content">${pageContent()}</div></main></div></div></div>`;
  }
'''
s=s[:start]+shell+s[end:]
s=s.replace("case'home':return home();", "case'home':return sceneHome();",1)
s=s.replace("case'tasks':return tasks();default:return home();", "case'tasks':return tasks();case'assistant':return sharedHub('assistant');case'automations':return sharedHub('automations');case'more':return sharedHub('more');case'task':return taskPreview();default:return sceneHome();",1)
start=s.index('  function home(){')
end=s.index('  function bank(){',start)
home=r'''  function sceneHome(){
    const module=sceneInfo[S.scene]||sceneInfo.office;
    return `<section class="launcher"><div class="launcher-heading"><span class="launcher-overline">MAKE ROOM FOR WHAT MATTERS</span><h1>知序，和你一起完成<span class="heading-dot">。</span></h1><div class="scene-tabs" role="tablist" aria-label="工作模块">${Object.entries(sceneInfo).map(([id,m])=>`<button id="scene-${id}" class="scene-tab ${S.scene===id?'selected':''}" role="tab" aria-selected="${S.scene===id}" aria-controls="scene-content" data-action="switch-scene" data-value="${id}">${I(m.icon)}${m.name}</button>`).join('')}</div><p class="launcher-subtitle">${module.subtitle}</p></div><div id="scene-content" role="tabpanel" aria-labelledby="scene-${S.scene}"><div class="task-shortcuts">${module.chips.map(([label,action])=>`<button class="task-shortcut" ${action==='建题'?'data-action="new-build"':action==='面试'?'data-action="setup-interview"':`data-action="task-template" data-value="${label}"`}>${label}</button>`).join('')}</div><div class="composer-wrap"><div class="composer"><textarea id="task-prompt" aria-label="任务描述" placeholder="${S.scene==='office'?'今天想一起完成什么？  @ 添加上下文，/ 选择 Agent 与技能':S.scene==='develop'?'说说你正在做的项目，或想解决的技术问题…':'描述你的想法，让我们把它变成看得见的方案…'}">${E(S.taskPrompt)}</textarea><div class="composer-attachments" id="composer-attachments">${(S.demoAttachments||[]).map(f=>`<span>${I('file')}${E(f)}</span>`).join('')}</div><div class="composer-toolbar"><button class="icon-btn add-context" data-action="add-context" aria-label="添加上下文">${I('plus')}</button><div class="composer-hint"><kbd>@</kbd> 上下文 <span>·</span> <kbd>/</kbd> 技能</div><div class="composer-tools"><button class="composer-model" data-action="model-picker">${I('spark')}<span>DeepSeek</span>${I('down')}</button><button class="icon-btn" data-action="composer-voice" aria-label="语音输入说明">${I('mic')}</button><button id="send-task" class="send-task ${S.taskPrompt.trim()?'ready':''}" data-action="submit-task" aria-label="发送任务" ${S.taskPrompt.trim()?'':'disabled'}>${I('arrow')}</button></div></div></div><div class="composer-context"><button class="context-picker" data-action="workspace-picker">${I('folder')}<span>${E(S.workspaceChoice||'选择工作空间')}</span>${I('down')}</button><span class="context-separator"></span><button class="context-picker" data-action="access-picker">${I('shield')}<span>${S.accessMode==='confirm-write'?'修改前确认':'只读访问'}</span>${I('down')}</button><span class="context-local">${I('check')} 由你选择本次资料范围</span></div></div><div class="suggestion-section"><div class="suggestion-heading"><span>从一个具体的任务开始</span><span class="suggestion-line"></span><button data-action="refresh-suggestions">换一组 ${I('refresh')}</button></div><div class="suggestion-grid">${module.suggestions.map(([icon,title,action,desc])=>`<button class="suggestion-card" data-action="${action==='建题'?'new-build':action==='面试'?'setup-interview':'task-template'}" ${action==='建题'||action==='面试'?'':`data-value="${E(title)}"`}><span class="suggestion-icon">${I(icon)}</span><div><strong>${title}</strong><p>${desc}</p></div><span class="suggestion-arrow">${I('arrow')}</span></button>`).join('')}</div></div><p class="launcher-footnote">先从一件小事开始。${S.scene==='office'?'题库、面试与学习资料，在同一个工作台里串起来。':S.scene==='develop'?'关联项目后，任务与资料共同沉淀。':'想法、过程与成果，留在同一处。'}</p></div></section>`;
  }
  function sharedHub(kind){
    if(kind==='assistant')return `${head('YOUR ASSISTANTS','为不同的工作，找到合适的助手。','入口始终共用，能力按任务组合。',btn('配置 Agent','nav','','settings','data-page="agents"'))}<div class="agent-shortcuts"><button class="agent-card" data-action="new-build"><div class="agent-glyph">${I('book')}</div><h3 style="margin-top:17px">面试题整理 Agent</h3><p>从岗位与项目出发，整理题目、回答要点和来源。</p><div class="agent-card-footer"><span>办公 · 知识整理</span>${I('arrow')}</div></button><button class="agent-card" data-action="setup-interview"><div class="agent-glyph olive">${I('mic')}</div><h3 style="margin-top:17px">AI 面试官 Agent</h3><p>文字或语音训练，回答、追问与复盘连在一起。</p><div class="agent-card-footer"><span>办公 · 面试训练</span>${I('arrow')}</div></button></div><div class="shared-hub-note">${I('layers')}学习复盘、开发和设计助手将在后续按场景扩展。当前页为前端布局评审。</div>`;
    if(kind==='automations')return `${head('AUTOMATIONS','让规律的事，按你的节奏发生。','定时任务是全局能力；这一版先展示入口与任务组织。',btn('新建计划 · 演示','new-schedule','','plus'))}<div class="task-list"><button class="task-row" data-action="new-schedule"><span class="task-icon">${I('clock')}</span><div class="grow"><strong>每周面试薄弱点复习</strong><small>每周日 20:00 · 仅为方案示例，未启用</small></div>${pill('未启用')}${I('chevron')}</button><button class="task-row" data-action="new-schedule"><span class="task-icon">${I('book')}</span><div class="grow"><strong>每周整理学习笔记</strong><small>根据选定材料生成复盘草稿 · 设计示例</small></div>${pill('草稿')}${I('chevron')}</button></div><p class="footer-caption">此原型不会创建真实计划或在后台执行任务。</p>`;
    return `${head('EXPLORE','更多可能，从这里继续。','办公、开发、设计共用这套工作台，具体能力随任务扩展。')}<div class="explore-grid">${[['book','面试题库','从主题与项目开始，逐步建立自己的题库。','bank'],['mic','AI 面试官','练习讲清楚问题，也讲清楚自己的经验。','interview'],['review','复习清单','让没讲清楚的知识，有机会再次练习。','review'],['bot','专家与工具配置','查看内置 Agent、自定义任务与工具配置。','agents']].map(([icon,name,desc,page])=>`<button class="explore-item" data-action="nav" data-page="${page}"><span class="agent-glyph olive">${I(icon)}</span><strong>${name}</strong><p>${desc}</p>${I('arrow')}</button>`).join('')}</div>`;
  }
  function taskPreview(){const t=S.currentTask||{title:'新任务',scene:S.scene,prompt:S.taskPrompt};return `${head('TASK PREVIEW',E(t.title),'任务会话布局演示 · 当前未调用模型或工具',btn('返回新建任务','nav','','plus','data-page="home"'))}<div class="builder-layout"><section class="panel"><div class="task-message user-message"><span class="avatar">我</span><div><strong>任务目标</strong><p>${E(t.prompt)}</p></div></div><div class="task-message agent-message"><span class="agent-glyph olive">${I('bot')}</span><div><strong>知序助手 <span class="sample-badge">演示</span></strong><p>已将你的目标整理成任务草稿。正式版会结合选定的工作空间和资料执行；当前只演示任务入口与结果区域。</p><div class="demo-plan"><span>${I('check')} 明确任务目标与资料范围</span><span>${I('clock')} 根据任务选择 Agent 与工具</span><span>${I('file')} 将结果保存在独立成果区</span></div></div></div><div class="action-row">${btn('改为整理面试题','new-build','','book')}${btn('进入 AI 面试官','setup-interview','primary','mic')}</div></section><aside class="summary-box"><h3>本次上下文</h3><div class="summary-line"><span>任务模块</span><span>${sceneInfo[t.scene]?.name||'办公'}</span></div><div class="summary-line"><span>工作空间</span><span>${E(S.workspaceChoice||'未选择')}</span></div><div class="summary-line"><span>访问方式</span><span>${S.accessMode==='confirm-write'?'修改前确认':'只读'}</span></div><div class="note-box">当前没有执行文件读取、上传、模型调用或修改操作。</div></aside></div>`;}
  function workspacePicker(){modal(`<div class="between"><h2>为这次任务选择空间</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${I('close')}</button></div><p>工作空间属于当前任务上下文，切换模块不会改变它。</p><div class="workspace-choices">${[['','暂不选择','直接从任务描述开始'],['tiangong_agent','tiangong_agent','Agent 学习与项目实践 · 只读关联'],['Java 项目与面试','Java 项目与面试','Java 工程经验与知识资料']].map(([value,name,desc])=>`<button class="workspace-choice ${S.workspaceChoice===value?'chosen':''}" data-action="choose-workspace" data-value="${value}">${I('folder')}<div><strong>${name}</strong><small>${desc}</small></div>${S.workspaceChoice===value?I('check'):I('chevron')}</button>`).join('')}</div><div class="modal-footer">${btn('管理资料与项目关联','nav','','settings','data-page="workspace"')}</div>`);}
'''
s=s[:start]+home+s[end:]
anchor="    case'nav':nav(el.dataset.page);break;"
handlers=r'''    case'nav':closeModal();nav(el.dataset.page);break;
    case'switch-scene':S.scene=val;render(true);break;
    case'task-template':S.taskPrompt=val;nav('home');document.getElementById('task-prompt')?.focus();break;
    case'workspace-picker':workspacePicker();break;
    case'choose-workspace':S.workspaceChoice=val;closeModal();render(true);toast(val?'已为本次任务选择空间：'+val:'本次任务暂不关联空间。');break;
    case'space-open':S.workspaceChoice=val;nav('workspace');break;
    case'access-picker':modal(`<h2>任务访问方式</h2><p>先明确范围，再让工具执行。当前为界面演示，不会实际修改文件。</p><div class="workspace-choices"><button class="workspace-choice" data-action="choose-access" data-value="read-only">${I('shield')}<div><strong>只读访问</strong><small>读取选定资料，不修改项目文件</small></div></button><button class="workspace-choice" data-action="choose-access" data-value="confirm-write">${I('edit')}<div><strong>修改前确认</strong><small>任何修改先展示方案，再由你确认</small></div></button></div>`);break;
    case'choose-access':S.accessMode=val;closeModal();render(true);break;
    case'model-picker':modal(`<h2>选择任务模型</h2><p>当前原型使用演示数据，没有连接真实模型。</p><div class="workspace-choice chosen">${I('spark')}<div><strong>DeepSeek</strong><small>已选方案 · 尚未连接服务</small></div>${I('check')}</div><div class="modal-footer">${btn('模型与工具设置','nav','','settings','data-page="settings"')}${btn('保持当前选择','close-modal','primary')}</div>`);break;
    case'add-context':modal(`<h2>添加任务上下文</h2><p>先选择本次需要的资料。以下为示例，不读取真实文件。</p><div class="workspace-choices">${['supervisor_agent.py','worker_tools.py','学习笔记.md'].map(f=>`<button class="workspace-choice" data-action="attach-demo" data-value="${f}">${I(f.endsWith('.py')?'code':'file')}<div><strong>${f}</strong><small>示例资料 · 不会上传</small></div>${I('plus')}</button>`).join('')}</div>`);break;
    case'attach-demo':S.demoAttachments=[...new Set([...(S.demoAttachments||[]),val])];closeModal();render(true);break;
    case'composer-voice':toast('首页语音输入仅展示入口；面试中的语音流程可在 AI 面试官体验。');break;
    case'refresh-suggestions':{const m=sceneInfo[S.scene];m.suggestions=[...m.suggestions.slice(1),m.suggestions[0]];render(true);break;}
    case'submit-task':{if(!S.taskPrompt.trim())return;const t={id:'task-'+Date.now(),title:S.taskPrompt.trim().slice(0,24),prompt:S.taskPrompt.trim(),scene:S.scene};S.demoTasks=[...(S.demoTasks||[]),t];S.currentTask=t;nav('task');break;}
    case'open-demo-task':S.currentTask=S.demoTasks.find(t=>t.id===id);nav('task');break;
    case'new-schedule':modal(`<h2>定时任务 · 布局演示</h2><p>这一页展示全局定时任务的组织方式。当前不会创建真实计划、触发提醒或后台调用。</p><div class="field"><label>计划名称</label><input class="input" value="每周面试薄弱点复习" readonly></div><div class="note-box">正式自动化留在后续阶段，先完成题库与面试的首个可用闭环。</div><div class="modal-footer">${btn('知道了','close-modal','primary')}</div>`);break;'''
assert s.count(anchor)==1
s=s.replace(anchor,handlers,1)
anchor="if(el.id==='answer')S.interview.answer=el.value;"
assert s.count(anchor)==1
s=s.replace(anchor,"if(el.id==='task-prompt'){S.taskPrompt=el.value;const send=document.getElementById('send-task');send.disabled=!el.value.trim();send.classList.toggle('ready',!!el.value.trim());}"+anchor,1)
anchor="document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();});"
assert s.count(anchor)==1
s=s.replace(anchor,"document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.target.id==='task-prompt'&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();if(S.taskPrompt.trim())document.getElementById('send-task')?.click();}});",1)
p.write_text(s,encoding='utf-8')
print('Shared navigation, three-scene launcher, contextual workspace picker and task-preview interactions written.')
